using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using SlopProX;
class V8BackendTests {
 static string filter="";static List<string> report=new List<string>();static int failed;static string output;
 static void Check(bool b,string reason){if(!b)throw new Exception(reason);}static void Test(string name,Action test){if(filter.Length>0&&!name.Contains(filter))return;try{test();report.Add("PASS "+name);}catch(Exception e){failed++;report.Add("FAIL "+name+" :: "+e);}File.WriteAllLines(output,report);}
 static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}
 static ProjectDocument Project(){var p=new ProjectDocument();var t=ProjectFactory.CreateTrack("ASIO sustained Sampler",TrackType.Midi);var r=ProjectFactory.CreateRegion("Test notes",0,128);for(int i=0;i<128;i++)r.Notes.Add(new MidiNote{StartBeat=i,LengthBeats=.5,Pitch=60+i%12,Velocity=64});t.Regions.Add(r);p.Tracks.Add(t);return p;}
 static int Main(string[] args){output=args[0];if(args.Length>1)filter=args[1];Directory.CreateDirectory(Path.GetDirectoryName(output));foreach(var d in WinMmDevices.MidiInputs())report.Add("MIDI INPUT "+d.Id+" "+d.Name);var driver=AsioDrivers.Enumerate().FirstOrDefault(d=>d.Name.Contains("FL Studio"));if(driver==null){report.Add("BLOCKED installed FL Studio ASIO not found");File.WriteAllLines(output,report);return 2;}report.Add("ACTUAL DRIVER "+driver.Name+" "+driver.Clsid);
 Test("ASIO continuous callback clock at 48000 Hz for 16 seconds, gain/pan graph changes and seeks",()=>{var settings=new AppSettings{AudioBackend="ASIO",AsioDriver=driver.Clsid,SampleRate=48000,BufferFrames=512};using(var engine=new ArrangementEngine(settings)){var p=Project();engine.SetProject(p);engine.Start(0);double last=engine.PositionBeat;for(int i=0;i<80;i++){Thread.Sleep(200);double now=engine.PositionBeat;Check(now>last,"ASIO playhead stalled at "+now+" iteration "+i);last=now;if(i%8==3){p.Tracks[0].Pan=i%16<8?-.7:.7;p.Tracks[0].GainDb=-18;engine.SetProject(p);}if(i==38){engine.Seek(16);last=engine.PositionBeat;}}Check(!engine.DeviceFailed,"ASIO reported device failure");report.Add("SUSTAINED seconds=16 finalBeat="+last);engine.Stop();}});
 Test("ASIO reconfiguration and repeated start/stop at 44100 / 48000 Hz",()=>{foreach(int rate in new[]{44100,48000}){long rendered=0,captured=0;Exception error=null;using(var stream=new AsioCompanion(new AppSettings{AudioBackend="ASIO",AsioDriver=driver.Clsid,SampleRate=rate,BufferFrames=512},(data,n,pos)=>{Interlocked.Add(ref rendered,n);Array.Clear(data,0,data.Length);},(data,n,c,pos)=>Interlocked.Add(ref captured,n))){stream.Failed+=e=>error=e;for(int i=0;i<10;i++){long before=stream.FramesPlayed;Thread.Sleep(200);Check(stream.FramesPlayed>before,"No callbacks at "+rate);}Check(error==null,error==null?"":error.Message);Check(rendered>rate&&captured>rate,"No sustained input/output callbacks");report.Add("ASIO rate="+rate+" rendered="+rendered+" captured="+captured+" underruns="+stream.Underruns);}}});
 Test("ASIO worker exit detected and engine Play reconnects its own driver process",()=>{using(var engine=new ArrangementEngine(new AppSettings{AudioBackend="ASIO",AsioDriver=driver.Clsid,SampleRate=48000,BufferFrames=512})){engine.SetProject(Project());Exception error=null;engine.Failed+=e=>error=e;engine.Start(0);Thread.Sleep(250);var stream=Field(engine,"_output");var ipc=Field(stream,"_ipc");var child=(Process)Field(ipc,"Process");int childId=child.Id;child.Kill();for(int i=0;i<25&&error==null;i++)Thread.Sleep(50);Check(error!=null&&engine.DeviceFailed,"Worker exit not detected");engine.Stop();engine.Start(4);Thread.Sleep(350);Check(engine.PositionBeat>4&&!engine.DeviceFailed,"Reconnected ASIO clock did not advance");report.Add("RECOVERY own worker PID="+childId);}});
 Test("WASAPI 48000 Hz selected virtual output remains active",()=>{var endpoint=WasapiStream.Devices(false).FirstOrDefault(d=>d.Name.Contains("7/8"));Check(endpoint!=null,"Virtual output not installed");using(var stream=new WasapiStream(endpoint.Id,false,false,48000,512,(data,n,c,pos)=>Array.Clear(data,0,data.Length))){Thread.Sleep(600);Check(stream.FramesPlayed>20000,"WASAPI clock did not advance");report.Add("WASAPI frames="+stream.FramesPlayed);}});
 if(args.Length>2)Test("Selected user ASIO driver sustained silent callback clock at 48000 Hz",()=>{Guid clsid;Check(Guid.TryParse(args[2],out clsid),"Invalid test ASIO CLSID");long render=0,capture=0;Exception failure=null;using(var stream=new AsioCompanion(new AppSettings{AudioBackend="ASIO",AsioDriver=clsid.ToString("B"),SampleRate=48000,BufferFrames=512},(data,n,pos)=>{Interlocked.Add(ref render,n);Array.Clear(data,0,data.Length);},(data,n,c,pos)=>Interlocked.Add(ref capture,n))){stream.Failed+=e=>failure=e;for(int i=0;i<32;i++){long before=stream.FramesPlayed;Thread.Sleep(250);Check(stream.FramesPlayed>before,"Selected driver stopped advancing at iteration "+i);Check(failure==null,failure==null?"":failure.Message);}report.Add("USER ASIO frames="+stream.FramesPlayed+" render="+render+" inputFrames="+capture+" inputChannels="+stream.InputChannels+" underruns="+stream.Underruns+"; output silence, no physical input retained");}});
 report.Add("NOT RUN physical MIDI keyboard performance, physical mic monitoring, all other ASIO vendors.");File.WriteAllLines(output,report);Console.WriteLine(String.Join(Environment.NewLine,report.ToArray()));return failed==0?0:1;
}
}
